function countInPulse(pulse){if(!ctx||soundMuted)return;const oscillator=ctx.createOscillator(),gain=ctx.createGain(),at=ctx.currentTime;oscillator.frequency.value=pulse===0?1100:800;gain.gain.setValueAtTime(Math.max(.0001,soundVolume*.18),at);gain.gain.exponentialRampToValueAtTime(.0001,at+.06);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(at);oscillator.stop(at+.07);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};}
