const isDemo=()=>mode==='learn'&&learnPlayback==='demo';
const demoVoices=new Map();
function syncDemo(){const active=new Map();for(const n of session.notes)if(n.beat<=session.beat&&n.beat+n.duration>session.beat)active.set(n.pitch,n.beat);for(const [pitch,onset] of demoVoices)if(active.get(pitch)!==onset){toneOff(pitch);demoVoices.delete(pitch);}for(const [pitch,onset] of active)if(!demoVoices.has(pitch)){toneOn(pitch,90,true);demoVoices.set(pitch,onset);}updateKeys();}
function syncLearnOptions(){ $('learnOptions').hidden=mode!=='learn';document.querySelectorAll('[data-learn]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.learn===learnPlayback));}

let instrument='piano',lesson=lessons[0],mode='learn',session,running=false,clock=performance.now(),saved={},access,input,stream,analyser,micNode,ctx,micFrame=0,micCandidate=null,micStable=0,micHeld=null,micSilence=0,opening=false;
const videoPlayer=new VideoPlayer({getSession:()=>session,isRunning:()=>running,onPlay:()=>begin(),onPause:()=>pause(),onSeek:seekPlayback,onSave:saveVideo,onSync:syncVideoTempo});
