try{const stored=localStorage.getItem('musicteacher.fingerMode');fingerMode=['off','numbers','colors'].includes(stored)?stored:localStorage.getItem('musicteacher.fingerings')==='on'?'numbers':'off';fingeringEnabled=fingerMode!=='off';}catch{}
const drumPlayer=new DrumPlayer(),drumOnset=new DrumOnset();
const sampler=new SamplePlayer({notify:({bank,state,error})=>{const name=soundBanks[bank].label;$('soundStatus').textContent=state==='loading'?'Loading '+name+'…':state==='ready'?name+' ready':state==='error'?name+' could not load. Use Retry samples.':name+' · loads when you play';$('soundStatus').dataset.state=state;$('retrySound').hidden=state!=='error';}});
