try{const stored=localStorage.getItem('musicteacher.volume');if(stored!==null&&Number.isFinite(Number(stored)))soundVolume=Math.max(0,Math.min(1,Number(stored)));soundMuted=localStorage.getItem('musicteacher.muted')==='true';}catch{}
function applySound(){sampler.setVolume(soundVolume,soundMuted);trackMixer.setVolume(soundVolume,soundMuted);if(typeof drumPlayer!=='undefined')drumPlayer.setVolume(soundVolume,soundMuted);$('soundVolume').value=Math.round(soundVolume*100);$('soundVolumeValue').textContent=Math.round(soundVolume*100)+'%';$('soundMute').checked=soundMuted;try{localStorage.setItem('musicteacher.volume',soundVolume);localStorage.setItem('musicteacher.muted',soundMuted);}catch{}}
$('soundVolume').oninput=()=>{soundVolume=Number($('soundVolume').value)/100;applySound();};$('soundMute').onchange=()=>{soundMuted=$('soundMute').checked;applySound();};applySound();
function selectSound(){if(instrument==='drums'){sampler.stopAll();$('soundStatus').textContent='Drum kit · synthesized percussion';$('retrySound').hidden=true;}else sampler.select(bankFor(instrument,transpose()));}
