function status(text){$('status').textContent=text;}
function setPlayButton(label){$('start').textContent=label.includes('Pause')?'Ⅱ':'▶';$('start').title=label.replace(/^[^A-Za-z]+/,'');$('start').setAttribute('aria-label',$('start').title);}
async function audio(loadSamples=true){ctx??=new AudioContext();sampler.connect(ctx);drumPlayer.connect(ctx);if(ctx.state!=='running')await ctx.resume();if(loadSamples&&instrument!=='drums')await sampler.prepare();}
function toneOn(pitch,velocity=90,preview=false){if(!ctx||(!preview&&$('source').value==='mic'))return;if(instrument==='drums'){if(ctx.state==='running')drumPlayer.hit(pitch,velocity);else ctx.resume().then(()=>{if(instrument==='drums')drumPlayer.hit(pitch,velocity);}).catch(()=>{});}else sampler.noteOn(pitch,velocity);}
function toneOff(pitch){sampler.noteOff(pitch);}

function press(pitch,source,velocity=90){if(instrument==='drums'&&pressed.has(source))release(source);if(pressed.has(source))return;const already=[...pressed.values()].includes(pitch);pressed.set(source,pitch);if(!already){toneOn(pitch,velocity);if(running&&!countIn.active&&!isDemo())session.press(pitch);}updateKeys();}
function release(source){const pitch=pressed.get(source);if(pitch===undefined)return;pressed.delete(source);if(![...pressed.values()].includes(pitch)){toneOff(pitch);session?.release(pitch);}updateKeys();}
function releaseAll(){for(const source of [...pressed.keys()])release(source);pointerNotes.clear();micHeld=null;micStable=0;micCandidate=null;}
let previewTimers=[],playbackEpoch=0;
function stopPreview(){demoVoices.clear();previewTimers.forEach(clearTimeout);previewTimers=[];sampler.stopAll();drumPlayer.stopAll();trackMixer.stop();}
function syncVideoTempo(){if(!session)return;const beat=session.beat;const linked=videoPlayer.active;$('tempo').disabled=linked;session.bpm=linked?videoPlayer.video.bpm:Number($('tempo').value);session.time=beat*60/session.bpm;$('bpm').textContent=(linked?Math.round(session.bpm*videoPlayer.rate*10)/10:session.bpm)+' BPM'+(linked?' (video)':'');}
function startScrub(){pause();videoPlayer.scrubbing=true;}
function finishScrub(){if(videoPlayer.active)videoPlayer.seek(session.beat);videoPlayer.scrubbing=false;videoPlayer.updatePosition();}
function scrubTo(beat){const end=Math.max(session.playbackEnd||0,...session.notes.map(n=>n.beat+n.duration));seekPlayback(Math.max(0,Math.min(end,beat)));$('feedback').textContent='Ready from beat '+(session.beat+1).toFixed(2)+' - press Play';}
fullSheet.enableSeeking({onStart:startScrub,onSeek:scrubTo,onEnd:finishScrub});
let rollScrubBeat=null;
new PlayheadDrag($('roll'),{hitTest:(x,y)=>{if(!session)return null;const r=$('roll').getBoundingClientRect(),beat=rollScrubBeat??session.beat;return Math.max(0,beat+(instrument==='piano'?(r.bottom-y)/73:(x-r.left-horizontalGeometry(r.width).line)/horizontalGeometry(r.width).unit));},onStart:()=>{rollScrubBeat=session.beat;startScrub();},onMove:scrubTo,onEnd:()=>{rollScrubBeat=null;finishScrub();}});
function seekPlayback(beat){releaseAll();stopPreview();countIn.cancel();session.seek(beat*60/session.bpm);updateScore();updateKeys();updateLyrics();fullSheet.update();}
async function saveVideo(video){if(lesson.library&&lesson.id.startsWith('user-')){const response=await fetch('/api/library/'+lesson.id+'/video',{method:'POST',headers:{'Content-Type':'application/json','X-MusicTeacher-Request':'library'},body:JSON.stringify({video})});const data=await response.json();if(!response.ok)throw Error(data.error||'Video could not be saved.');}lesson.video=video;try{localStorage.setItem('musicteacher.video.'+lesson.id,JSON.stringify(video));}catch{}}
function pause(){videoPlayer.pause();countIn.cancel();playbackEpoch++;stopPreview();running=false;releaseAll();setPlayButton('▶ Continue');}
function stopInput(){if(input){input.onmidimessage=null;input.close().catch(()=>{});input=null;}stream?.getTracks().forEach(t=>t.stop());stream=null;micNode?.disconnect();micNode=null;analyser=null;releaseAll();$('connect').textContent='Connect input';$('heard').textContent='—';}
function startFresh(){pause();drumOnset.reset();const rawScore=makeNotes(lesson,base(),transpose());const score=instrument==='singing'?vocalScore(rawScore,Number($('voiceRange').value)):rawScore;session=new Session(instrument==='drums'&&$('source').value==='mic'&&!isDemo()?acousticScore(score):score,{mode:isDemo()?'demo':mode,bpm:Number($('tempo').value),meter:lesson.meter||'4/4',countIn:false});session.tablature=lesson.tablature;trackMixer.setSong(lesson);trackMixer.demo=isDemo();trackMixer.applyVolume();renderMixer();session.playbackEnd=trackMixer.endBeat;videoPlayer.setSong(lesson);syncVideoTempo();videoPlayer.seek(0);setPlayButton('▶ Start lesson');$('feedback').textContent='Press Start when you’re ready';if(instrument==='singing'){$('vocalMeter').value=0;$('vocalReadout').textContent='Sing a clear, comfortable note';}$('combo').textContent='0';renderLyrics();updateScore();updateKeys();fullSheet.setScore(session,lesson,instrument,instrument==='singing'?Number($('voiceRange').value):0);updatePersonalContext();}
function updateScore(){const visible=showScores&&!isDemo();$('scoreStats').hidden=!visible;document.querySelector('.earned-compact').hidden=!showScores;$('liveScore').textContent=(session?.score||0).toLocaleString();$('combo').textContent=session?.combo||0;const judged=session?session.judged+session.wrong+session.notes.filter(n=>n.state==='miss').length:0;$('liveAccuracy').textContent=judged?Math.round(session.judged/judged*100)+'%':'—';$('bestScore').textContent=(saved[progressKey()]?.bestScore||0).toLocaleString();}
$('showScores').checked=showScores;$('showScores').onchange=()=>{showScores=$('showScores').checked;try{localStorage.setItem('musicteacher.showScores',String(showScores));}catch{}if(!showScores&&$('results').open)$('results').close();renderLessons();updateScore();};
let lyricCues=[],lyricNodes=[],lyricIndex=-2,lyricWidth=-1;
function renderLyrics(){ $('vocalLyrics').hidden=instrument!=='singing';lyricCues=instrument==='singing'?vocalCues(session.notes):[];lyricIndex=-2;lyricWidth=-1;lyricNodes=lyricCues.map((cue,i)=>{const el=document.createElement('span');el.textContent=cue.text;el.title=cue.text;el.className='lyric-word';return el;});$('lyricsTrack').replaceChildren(...lyricNodes);$('currentLyric').textContent='';updateLyrics();}
function updateLyrics(){if(sheetMode||instrument!=='singing'||!session)return;const width=$('lyricsTrack').parentElement.clientWidth,{line,unit}=horizontalGeometry(width);$('lyricsTrack').style.transform='translateX('+(line-session.beat*unit)+'px)';$('vocalLyrics').style.setProperty('--lyric-marker',line+'px');let active=-1;for(let i=0;i<lyricCues.length;i++){const cue=lyricCues[i];if(width!==lyricWidth){lyricNodes[i].style.left=cue.beat*unit+'px';const gap=lyricCues[i+1]?lyricCues[i+1].beat-cue.beat:cue.duration;lyricNodes[i].style.maxWidth=Math.max(35,gap*unit-8)+'px';}if(session.beat>=cue.beat&&session.beat<cue.beat+cue.duration)active=i;}lyricWidth=width;if(active!==lyricIndex){lyricIndex=active;lyricNodes.forEach((el,i)=>{el.classList.toggle('current',i===active);if(i===active)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current');});$('currentLyric').textContent=active>=0?lyricCues[active].text:'';}}
function stars(n){return '★'.repeat(n)+'☆'.repeat(3-n);}
function curriculumLessons(){return [...harmonyLessons(instrument,$('source').value),...(instrument==='guitar'?guitarChordLessons():[])];}
function renderLessons(){const visible=[...(instrument==='drums'?drumLessons:instrument==='singing'?singingLessons:lessons),...curriculumLessons(),...(theoryLesson?[theoryLesson]:[])].filter((l,i,a)=>(!l.piano||(instrument==='piano'&&$('source').value!=='mic'))&&a.findIndex(x=>x.id===l.id)===i);lesson=visible.find(l=>l.id===lesson.id)||visible[0];$('lessons').replaceChildren(...visible.map(l=>{const option=document.createElement('option');option.value=l.id;const best=Math.max(0,...Object.entries(saved).filter(([k])=>k.startsWith(instrument+':')&&k.split(':')[3]===l.id).map(([,v])=>Number(v.stars)||0));option.textContent=l.title+(showScores&&best?' · '+'★'.repeat(best):'');option.selected=l===lesson;return option;}));$('lessons').onchange=()=>{lesson=visible.find(l=>l.id===$('lessons').value)||visible[0];renderHeading();renderKeys();startFresh();};$('earned').textContent=Object.values(saved).reduce((n,v)=>n+(Number(v.stars)||0),0);}
function renderView(){tabAvailable=['guitar','bass'].includes(instrument);applySheetMode();document.querySelector('.stage').dataset.guide=['sax','harmonica'].includes(instrument)?'diagram':'hands';$('fingerModes').hidden=!['piano','guitar','bass'].includes(instrument);document.querySelector('.fingering-switch').hidden=instrument!=='sax';const piano=instrument==='piano',drum=instrument==='drums',neck=instrument==='guitar'||instrument==='bass';document.querySelector('.stage').dataset.view=piano?'piano':drum?'drums':neck?'neck':'staff';$('viewHint').textContent=piano?'Follow the notes down to the keys.':neck?'Standard tuning · Numbers are frets · Thin strings at the top · Play at the left marker':instrument==='sax'?'Treble clef · Written notes · Play when each note reaches the left marker':'Treble clef · C diatonic harmonica · Play when each note reaches the left marker';$('keys').hidden=!piano&&!drum&&$('source').value!=='screen';$('keys').classList.toggle('drum-pads',drum);$('drumInputHelp').hidden=!drum;$('drumSensitivityLabel').hidden=!drum||$('source').value!=='mic';$('roll').setAttribute('aria-label',piano?'Falling piano notes.':drum?'Drum rhythm lanes. Play hits at the left marker.':neck?'Right-to-left scrolling fretboard. Strings and fret numbers show what to play.':'Right-to-left scrolling treble staff. Notes show written pitch.');}
function renderHeading(){renderView();$('lessonTitle').textContent=lesson.title;$('lessonTag').textContent=lesson.tag;$('description').textContent=lesson.description;$('tip').textContent=(lesson.library||lesson.curriculum)?lesson.description:lesson.theory?(instrument==='guitar'||instrument==='bass'?'Follow the displayed string and fret. Pitch detection checks the note; the position diagram guides where to play it.':instrument==='sax'?'Read the written pitch on the staff. Your selected sax transposition determines the sounding pitch.':instrument==='harmonica'?'Use a C diatonic harmonica. Follow the highlighted hole: BLOW means breathe out; DRAW means breathe in.':'Follow the notes in the selected key and octave. Use Learn to explore the pattern at your own pace.'):profiles[instrument].tip;}
function renderKeys(){renderView();if(instrument==='drums'){keyRects.clear();$('keys').replaceChildren(...drumPads.map(p=>{const b=document.createElement('button');b.dataset.note=p.note;b.style.setProperty('--pad-color',p.color);b.textContent=p.key+' · '+p.name;b.setAttribute('aria-label','Play '+p.name);b.onclick=e=>{if(e.detail===0){audio(false).then(()=>{press(p.note,'pad:'+p.note);setTimeout(()=>release('pad:'+p.note),80);});}};return b;}));return;}const p=profiles[instrument];let low=instrument==='piano'&&$('keyboard').value==='fm1'?53:p.low,high=instrument==='piano'&&$('keyboard').value==='fm1'?79:p.high;if(lesson.notes){low=Math.min(low,...lesson.notes.map(n=>n.written));high=Math.max(high,...lesson.notes.map(n=>n.written));}const whites=[];for(let n=low;n<=high;n++)if(!black(n))whites.push(n);const width=100/whites.length;let wi=0;keyRects.clear();$('keys').replaceChildren();for(let n=low;n<=high;n++){const isBlack=black(n);const left=isBlack?(wi-.3)*width:wi++*width;const w=isBlack?width*.6:width;keyRects.set(n,{left,width:w});const btn=document.createElement('button');btn.dataset.note=n;btn.className=isBlack?'black':'';if(instrument==='piano'){btn.style.left=left+'%';btn.style.width=w+'%';}btn.textContent=noteName(n);btn.setAttribute('aria-label','Play '+noteName(n));btn.onkeydown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(!e.repeat){audio().catch(()=>{});press(n+transpose(),'button:'+n);}}};btn.onkeyup=e=>{if(e.code==='Space'||e.code==='Enter')release('button:'+n);};btn.onclick=e=>{if(e.detail===0){audio().catch(()=>{});press(n+transpose(),'accessible:'+n);setTimeout(()=>release('accessible:'+n),100);}};btn.onblur=()=>release('button:'+n);$('keys').append(btn);}}
function guideFor(n){return fingeringFor(n,instrument,lesson,base());}
function guideLabel(n){if(instrument==='harmonica'){const g=guideFor(n);return g?'HOLE '+g.hole+' '+(g.breath==='B'?'BLOW':'DRAW'):'';}return fingeringEnabled?(guideFor(n)?.short||''):'';}
function updateFingering(){const panel=$('fingeringLegend');const visible=!['drums','singing'].includes(instrument)&&(fingeringEnabled||instrument==='harmonica'||lesson.chordDiagrams);panel.classList.toggle('has-chord-diagram',!!lesson.chordDiagrams);panel.hidden=!visible;if(!visible)return;const next=guideTarget(session);const notes=next?session.notes.filter(n=>(session.mode==='demo'||n.state==='pending')&&n.beat===next.beat):[];const guides=notes.map(guideFor);const key=JSON.stringify([instrument,guides,fingerMode]);if(key!==legendKey){legendKey=key;panel.innerHTML=next?legendHTML(guides,instrument,fingerMode==='colors'):'<p>Lesson complete.</p>';}}
function syncFingerModes(){document.querySelectorAll('[data-fingers]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fingers===fingerMode));}
document.querySelectorAll('[data-fingers]').forEach(b=>b.onclick=()=>{fingerMode=b.dataset.fingers;fingeringEnabled=fingerMode!=='off';$('fingerings').checked=fingeringEnabled;try{localStorage.setItem('musicteacher.fingerMode',fingerMode);}catch{}syncFingerModes();updateFingering();});
syncFingerModes();
function noteFingerColor(n){return fingerMode==='colors'?guideColor(guideFor(n)):null;}
$('fingerings').checked=fingeringEnabled;$('fingerings').onchange=()=>{fingeringEnabled=$('fingerings').checked;try{localStorage.setItem('musicteacher.fingerings',fingeringEnabled?'on':'off');}catch{}updateFingering();};
function updateKeys(){if(!session)return;const next=session.next;const targets=new Set(session.notes.filter(n=>n.state==='pending'&&next&&n.beat===next.beat).map(n=>n.written));for(const b of $('keys').children){const n=Number(b.dataset.note);b.classList.toggle('target',targets.has(n));b.classList.toggle('down',([...pressed.values()].includes(n+transpose())||demoVoices.has(n+transpose())));}let upcoming=next?session.notes.filter(n=>n.state==='pending'&&n.beat===next.beat).map(n=>instrument==='drums'?($('source').value==='mic'?'Any drum hit':drumPads.find(p=>p.note===n.written)?.name||'Drum'):(n.spelling?.label||noteName(n.written))).join(' + '):'Finished';if(next&&tunings[instrument]){const pos=next.position||fretFor(next.pitch,instrument);if(pos)upcoming+=' · '+noteName(tunings[instrument][pos.string])+' string, fret '+pos.fret;}$('next').textContent=upcoming;updateFingering();}
function changeProfile(name){if(!instrumentAvailable(name)){status(instrumentNotice(name));return;}pause();stopInput();instrument=name;selectSound();theoryLesson=null;refreshTheory();for(const b of $('instruments').children)b.classList.toggle('selected',b.dataset.instrument===name);$('voiceRangeLabel').hidden=name!=='singing';$('vocalTuner').hidden=name!=='singing';$('pianoLabel').hidden=name!=='piano';$('transposeLabel').hidden=name!=='sax';$('source').value=name==='piano'||name==='drums'?'screen':'mic';$('source').querySelector('option[value=mic]').textContent=name==='drums'?'Acoustic drums · timing only':'Microphone / interface';sourceChanged();renderKeys();renderHeading();startFresh();}
for(const id of instrumentOrder){const p=profiles[id],b=document.createElement('button');b.innerHTML=instrumentIcon(id);b.append(document.createTextNode(p.name));b.dataset.instrument=id;b.disabled=!instrumentAvailable(id);if(b.disabled){const badge=document.createElement('small');badge.textContent='Coming soon';b.append(badge);b.title=instrumentNotice(id);}b.onclick=()=>changeProfile(id);$('instruments').append(b);}
